fn exec_turns_to_defeat(health: i8, strength: i8) -> i64 {
    // Calculate the number of turns required to defeat an opponent
    (health as i64 + strength as i64 - 1) / strength as i64
}

fn solve(a: i8, b: i8, c: i8, d: i8) -> String {
    // Calculate the number of turns Takahashi needs to defeat Aoki
    let takahashi_turns = exec_turns_to_defeat(c, b);
    // Calculate the number of turns Aoki needs to defeat Takahashi
    let aoki_turns = exec_turns_to_defeat(a, d);
    
    // Compare the turns and return the result
    if takahashi_turns <= aoki_turns {
        "Yes".to_string()
    } else {
        "No".to_string()
    }
}

